import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:image_picker/image_picker.dart';
import 'package:permission_handler/permission_handler.dart';
import 'package:speech_to_text/speech_to_text.dart';
import 'core/providers/ai_router.dart';
void main()=>runApp(const AiOsApp());
const secureStorage=FlutterSecureStorage(); const native=MethodChannel('ai_os/native');
class AiOsApp extends StatelessWidget{const AiOsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'AI OS',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const MainShell());}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}class _MainShellState extends State<MainShell>{int i=0;@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:IndexedStack(index:i,children:const[ChatPage(),AiRoomPage(),HistoryPage(),SettingsPage()])),bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(v)=>setState(()=>i=v),destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'채팅'),NavigationDestination(icon:Icon(Icons.hub_outlined),label:'AI 대화방'),NavigationDestination(icon:Icon(Icons.history),label:'기록'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'설정')]));}
class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage> createState()=>_ChatPageState();}class _ChatPageState extends State<ChatPage>{final input=TextEditingController(),stt=SpeechToText();final msgs=<Map<String,String>>[];String? name,text;bool busy=false,listening=false;AiRouter get router=>const AiRouter(secureStorage);Future<void> doc()async{try{final r=await native.invokeMapMethod<String,dynamic>('openDocument');if(r!=null&&mounted)setState((){name=r['name']?.toString();text=r['text']?.toString();});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}Future<void> add()async=>showModalBottomSheet<void>(context:context,builder:(x)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.camera_alt),title:const Text('카메라 촬영'),onTap:()async{Navigator.pop(x);if(await Permission.camera.request().isGranted){final f=await ImagePicker().pickImage(source:ImageSource.camera);if(f!=null&&mounted)setState(()=>name=f.name);}}),ListTile(leading:const Icon(Icons.photo),title:const Text('사진 선택'),onTap:()async{Navigator.pop(x);final f=await ImagePicker().pickImage(source:ImageSource.gallery);if(f!=null&&mounted)setState(()=>name=f.name);}),ListTile(leading:const Icon(Icons.description),title:const Text('문서 선택'),subtitle:const Text('TXT · MD · CSV · JSON 등 텍스트 문서 내용 읽기'),onTap:(){Navigator.pop(x);doc();})])));Future<void> voice()async{if(listening){await stt.stop();if(mounted)setState(()=>listening=false);return;}if(!await Permission.microphone.request().isGranted)return;if(!await stt.initialize())return;if(mounted)setState(()=>listening=true);await stt.listen(onResult:(r){input.text=r.recognizedWords;if(r.finalResult&&mounted)setState(()=>listening=false);});}Future<void> send()async{final q=input.text.trim();if(q.isEmpty&&name==null)return;setState((){msgs.add({'u':q.isEmpty?'${name??'첨부'} 분석':q,'a':''});input.clear();busy=true;});try{var p=q.isEmpty?'첨부 자료를 분석해줘':q;if((text??'').trim().isNotEmpty)p+='\n\n첨부 문서:\n$text';final r=await router.ask(p);if(mounted)setState(()=>msgs.add({'u':'','a':'${r.text}\n\n— ${r.provider}'}));}catch(e){if(mounted)setState(()=>msgs.add({'u':'','a':'AI 연결 실패\n$e'}));}finally{if(mounted)setState((){busy=false;name=null;text=null;});}}@override Widget build(BuildContext c)=>Column(children:[const ListTile(title:Text('AI OS',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:Text('무료 AI 우선 · 자동 Fallback')),Expanded(child:msgs.isEmpty?const Center(child:Text('무엇을 도와드릴까요?',style:TextStyle(fontSize:20))):ListView.builder(itemCount:msgs.length,itemBuilder:(_,n){final m=msgs[n],u=m['u']!.isNotEmpty;return Align(alignment:u?Alignment.centerRight:Alignment.centerLeft,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(u?m['u']!:m['a']!))));})),if(name!=null)ListTile(leading:const Icon(Icons.attach_file),title:Text(name!),subtitle:Text(text==null?'첨부됨':'내용 읽기 완료')),if(busy)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:add,icon:const Icon(Icons.add_circle_outline)),Expanded(child:TextField(controller:input,minLines:1,maxLines:5,decoration:const InputDecoration(hintText:'메시지',border:OutlineInputBorder()))),IconButton(onPressed:voice,icon:Icon(listening?Icons.mic:Icons.mic_none)),IconButton(onPressed:busy?null:send,icon:const Icon(Icons.send))]))]);}
class AiRoomPage extends StatefulWidget{const AiRoomPage({super.key});@override State<AiRoomPage> createState()=>_AiRoomPageState();}class _AiRoomPageState extends State<AiRoomPage>{final topics=<String>['AI OS 개발'];String topic='AI OS 개발';final input=TextEditingController();final lines=<String>[];bool busy=false;AiRouter get router=>const AiRouter(secureStorage);void newTopic(){final c=TextEditingController();showDialog<void>(context:context,builder:(d)=>AlertDialog(title:const Text('새 주제'),content:TextField(controller:c),actions:[FilledButton(onPressed:(){if(c.text.trim().isNotEmpty)setState((){topics.add(c.text.trim());topic=c.text.trim();lines.clear();});Navigator.pop(d);},child:const Text('생성'))]));}Future<void> send()async{final q=input.text.trim();if(q.isEmpty||busy)return;setState((){lines.add('나: $q');input.clear();busy=true;});for(final role in ['Planner','Reviewer','Judge']){try{final r=await router.ask('AI 회의 주제: $topic\n역할: $role\n사용자 요청: $q\n이 역할에 맞게 한국어로 답해.');if(mounted)setState(()=>lines.add('$role (${r.provider}): ${r.text}'));}catch(e){if(mounted)setState(()=>lines.add('$role: AI 연결 실패 - $e'));break;}}if(mounted)setState(()=>busy=false);}@override Widget build(BuildContext c)=>Column(children:[ListTile(title:const Text('AI 대화방',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:DropdownButton<String>(value:topic,isExpanded:true,items:topics.map((t)=>DropdownMenuItem(value:t,child:Text(t))).toList(),onChanged:(v){if(v!=null)setState(()=>topic=v);}),trailing:IconButton(onPressed:newTopic,icon:const Icon(Icons.add))),Expanded(child:ListView.builder(itemCount:lines.length,itemBuilder:(_,i)=>ListTile(title:Text(lines[i])))),if(busy)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:input,decoration:const InputDecoration(hintText:'AI 회의에 참여',border:OutlineInputBorder()))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]);}
class HistoryPage extends StatelessWidget{const HistoryPage({super.key});@override Widget build(BuildContext c)=>const Center(child:Text('대화 및 작업 기록'));}
class SettingsPage extends StatefulWidget{const SettingsPage({super.key});@override State<SettingsPage> createState()=>_SettingsPageState();}class _SettingsPageState extends State<SettingsPage> with WidgetsBindingObserver{bool freeFirst=true,paid=false,mic=false,cam=false;final enabled=<String,bool>{'Gemini':true,'Groq':false,'OpenRouter Free':false,'Hugging Face':false,'OpenAI API':false,'Claude API':false};AiRouter get router=>const AiRouter(secureStorage);@override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);load();}@override void dispose(){WidgetsBinding.instance.removeObserver(this);super.dispose();}@override void didChangeAppLifecycleState(AppLifecycleState s){if(s==AppLifecycleState.resumed)load();}Future<void> load()async{final m=await Permission.microphone.isGranted,c=await Permission.camera.isGranted;freeFirst=(await secureStorage.read(key:'free_first'))!='false';paid=(await secureStorage.read(key:'paid_enabled'))=='true';for(final k in enabled.keys.toList()){final v=await secureStorage.read(key:'provider_$k');if(v!=null)enabled[k]=v=='true';}if(mounted)setState((){mic=m;cam=c;});}Future<void> request(Permission p)async{final s=await p.request();if(s.isPermanentlyDenied)await openAppSettings();await load();}Future<void> toggle(String k,bool v)async{setState(()=>enabled[k]=v);await secureStorage.write(key:'provider_$k',value:'$v');}String keyName(String p)=>p=='Gemini'?'gemini_api_key':'${p.toLowerCase().replaceAll(' ','_')}_api_key';Future<void> keyDialog(String p)async{final c=TextEditingController(text:await secureStorage.read(key:keyName(p))??'');if(!mounted)return;await showDialog<void>(context:context,builder:(d)=>AlertDialog(title:Text('$p API 설정'),content:TextField(controller:c,obscureText:true,decoration:const InputDecoration(labelText:'API Key',border:OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('취소')),FilledButton(onPressed:()async{await secureStorage.write(key:keyName(p),value:c.text.trim());if(d.mounted)Navigator.pop(d);},child:const Text('저장'))]));}Future<void> test(String p)async{try{final r=await router.test(p);if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$p 연결 성공: $r')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$p 연결 실패: $e')));}}@override Widget build(BuildContext c)=>ListView(children:[const ListTile(title:Text('설정',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:Text('AI Provider · API · 권한')),SwitchListTile(value:freeFirst,onChanged:(v){setState(()=>freeFirst=v);secureStorage.write(key:'free_first',value:'$v');},title:const Text('무료 AI 우선')),SwitchListTile(value:paid,onChanged:(v){setState(()=>paid=v);secureStorage.write(key:'paid_enabled',value:'$v');},title:const Text('유료 API 사용 허용'),subtitle:const Text('OFF이면 OpenAI/Claude 자동 호출 차단')),const Divider(),...enabled.entries.map((e)=>Card(child:Column(children:[SwitchListTile(value:e.value,onChanged:(v)=>toggle(e.key,v),title:Text(e.key)),Row(mainAxisAlignment:MainAxisAlignment.end,children:[TextButton.icon(onPressed:()=>keyDialog(e.key),icon:const Icon(Icons.key),label:const Text('API')),TextButton.icon(onPressed:()=>test(e.key),icon:const Icon(Icons.wifi_tethering),label:const Text('연결 테스트'))])]))),const Divider(),ListTile(leading:const Icon(Icons.mic),title:const Text('마이크'),subtitle:Text(mic?'허용됨 ✓':'음성 입력에 필요'),trailing:mic?null:TextButton(onPressed:()=>request(Permission.microphone),child:const Text('요청'))),ListTile(leading:const Icon(Icons.camera_alt),title:const Text('카메라'),subtitle:Text(cam?'허용됨 ✓':'촬영에 필요'),trailing:cam?null:TextButton(onPressed:()=>request(Permission.camera),child:const Text('요청'))),const ListTile(leading:Icon(Icons.description),title:Text('문서'),subtitle:Text('Android 시스템 문서 선택기 사용')),const Divider(),const ListTile(title:Text('AI OS'),subtitle:Text('Version 0.5.0\nCreator: Daehyun Kang'))]);}}
